import { OpenResponses } from "../protocols/open-responses.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { ProviderID } from "../schema/index.js";
import { GoogleVertexShared } from "./google-vertex-shared.js";
export const id = ProviderID.make("google-vertex");
const route = Route.make({
    id: "google-vertex-responses",
    provider: id,
    providerMetadataKey: "vertex",
    protocol: OpenResponses.protocol,
    endpoint: Endpoint.path(OpenResponses.PATH),
    transport: OpenResponses.httpTransport,
    options: { providerOptions: { store: false, include: ["reasoning.encrypted_content"] } },
});
export const routes = [route];
const configuredRoute = (input) => GoogleVertexShared.oauthRoute(route, "Responses", input, (project, location) => `https://aiplatform.googleapis.com/v1/projects/${project}/locations/${location}/endpoints/openapi`);
export const configure = (input = {}) => {
    const route = configuredRoute(input);
    return {
        id,
        model: (modelID) => route.model({ id: modelID }),
        configure,
    };
};
export const provider = {
    id,
    configure,
};
export const model = (modelID, settings = {}) => configure(GoogleVertexShared.oauthSettings("Responses", settings)).model(modelID);
